import{_ as t,a as s,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Get Wishlist Items","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-wishlists","title":"Get Wishlist Items","description":"Retrieve the authenticated customer's wishlist items for the current channel, oldest first.","request":"GET /api/shop/wishlists\\nAccept: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 2\\nX-Page: 1\\nX-Per-Page: 30\\nX-Total-Pages: 1\\n\\n[\\n  {\\n    \\"id\\": 210,\\n    \\"createdAt\\": \\"2026-08-07T15:48:07+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T15:48:07+05:30\\",\\n    \\"product\\": \\"/api/shop/products/126\\",\\n    \\"customer\\": \\"/api/shop/customers/122\\",\\n    \\"channel\\": \\"/api/shop/channels/1\\"\\n  },\\n  {\\n    \\"id\\": 211,\\n    \\"createdAt\\": \\"2026-08-07T15:52:41+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T15:52:41+05:30\\",\\n    \\"product\\": \\"/api/shop/products/127\\",\\n    \\"customer\\": \\"/api/shop/customers/122\\",\\n    \\"channel\\": \\"/api/shop/channels/1\\"\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid Bearer token","solution":"Login and provide a valid customer authentication token"},{"error":"Empty array","cause":"The customer has saved nothing on the current channel","solution":"The wishlist is per channel — an item saved on another channel does not appear here"}]},{"id":"list-wishlists-newest-first","title":"Get Wishlist Items (newest first)","description":"Sort the wishlist so the most recently added item appears first.","request":"GET /api/shop/wishlists?sort=created_at&order=desc\\nAccept: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 211,\\n    \\"createdAt\\": \\"2026-08-07T15:52:41+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T15:52:41+05:30\\",\\n    \\"product\\": \\"/api/shop/products/127\\",\\n    \\"customer\\": \\"/api/shop/customers/122\\",\\n    \\"channel\\": \\"/api/shop/channels/1\\"\\n  },\\n  {\\n    \\"id\\": 210,\\n    \\"createdAt\\": \\"2026-08-07T15:48:07+05:30\\",\\n    \\"updatedAt\\": \\"2026-08-07T15:48:07+05:30\\",\\n    \\"product\\": \\"/api/shop/products/126\\",\\n    \\"customer\\": \\"/api/shop/customers/122\\",\\n    \\"channel\\": \\"/api/shop/channels/1\\"\\n  }\\n]\\n","commonErrors":[{"error":"Order unchanged","cause":"sort names a column the endpoint does not accept, so it falls back to id ascending","solution":"Sort by id or created_at only"}]}]},"headers":[],"relativePath":"api/rest-api/shop/wishlist/list.md","filePath":"api/rest-api/shop/wishlist/list.md","lastUpdated":1786429091000}`),r={name:"api/rest-api/shop/wishlist/list.md"};function d(i,e,n,c,h,l){return a(),s("div",null,e[0]||(e[0]=[o('<h1 id="get-wishlist-items" tabindex="-1">Get Wishlist Items <a class="header-anchor" href="#get-wishlist-items" aria-label="Permalink to &quot;Get Wishlist Items&quot;">​</a></h1><p>Retrieve the authenticated customer&#39;s wishlist items for the current channel.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/wishlists</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Customer Bearer token (<code>Bearer &lt;accessToken&gt;</code>)</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sort</code></td><td>No</td><td><code>id</code></td><td>Column to sort by — <code>id</code> or <code>created_at</code>. The compound form <code>created_at-desc</code> (<code>&lt;column&gt;-&lt;direction&gt;</code>) is also accepted.</td></tr><tr><td><code>order</code></td><td>No</td><td><code>asc</code></td><td>Sort direction — <code>asc</code> or <code>desc</code>. Use <code>desc</code> to return the most recently added items first.</td></tr></tbody></table><p>By default the wishlist is returned oldest-first (the order items were added). To show the newest item at the top, pass <code>?sort=created_at&amp;order=desc</code> (or the shorthand <code>?sort=created_at-desc</code>).</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>A bare JSON array of wishlist rows. Each row identifies its product, customer, and channel by <strong>path reference, not as a nested object</strong> — fetch the product separately to render a card.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Wishlist row ID. Use it on <a href="/api/rest-api/shop/wishlist/delete.html">Delete</a> and <a href="/api/rest-api/shop/wishlist/move-to-cart.html">Move to Cart</a>.</td></tr><tr><td><code>product</code></td><td>string</td><td>Path of the saved product, e.g. <code>/api/shop/products/126</code>. The trailing segment is the product ID.</td></tr><tr><td><code>customer</code></td><td>string</td><td>Path of the owning customer.</td></tr><tr><td><code>channel</code></td><td>string</td><td>Path of the channel the item was saved on.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>Pagination is reported in headers, not in the body: <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, <code>X-Total-Pages</code>.</p><p>Over GraphQL the same rows expose <code>product</code>, <code>customer</code>, and <code>channel</code> as nested objects that can be selected in one query — see <a href="/api/graphql-api/shop/queries/get-wishlist.html">Get Wishlist</a>.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Wishlist page</strong> — read the array, take the numeric ID from the end of each <code>product</code> path, and fetch those products to render names, prices, and images.</li><li><strong>&quot;Saved&quot; badge count</strong> — read <code>X-Total-Count</code> from the headers instead of counting the array, which only holds the current page.</li><li><strong>Newest-first view</strong> — <code>?sort=created_at&amp;order=desc</code> puts the latest save on top, which matches the &quot;just added&quot; confirmation a heart button produces.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Do not expect product details inline</strong> — the row carries a path only; a page that renders products needs a second call per product, or the GraphQL query instead.</li><li><strong>Read the count from the header</strong> — the body is one page, so <code>array.length</code> under-reports a long wishlist.</li><li><strong>Remember the channel scope</strong> — the same customer sees a different wishlist per channel, so a missing item usually means a different channel, not a lost row.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/wishlist/create.html">Create Wishlist Item</a> — add a product; rejects one already saved</li><li><a href="/api/rest-api/shop/wishlist/toggle.html">Toggle Wishlist Item</a> — add or remove in one call, for a heart icon</li><li><a href="/api/rest-api/shop/wishlist/move-to-cart.html">Move Wishlist Item to Cart</a> — add the saved product to the cart and drop the row</li><li><a href="/api/rest-api/shop/wishlist/delete-all.html">Delete All Wishlist Items</a> — clear the whole wishlist on this channel</li></ul>',20)]))}const m=t(r,[["render",d]]);export{u as __pageData,m as default};
